package com.idgs17.rate.config;import org.springframework.context.annotation.*;import org.springframework.web.cors.*;import java.util.List;@Configuration public class CorsConfig{@Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(System.getenv().getOrDefault("FRONTEND_ORIGIN","http://localhost:4200")));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(false);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
